//! 🦴️ Skins own complete source references and ordered joint memberships.
use super::*;
pub(super) fn project(write:&mut Write<'_,'_>,skins:&[GltfSkin])->Result<(),String>{write.check(skins.len())?;for(position,skin)in skins.iter().enumerate(){let [inverse_high,inverse_low]=optional_index(skin.inverse_bind_matrices);let [skeleton_high,skeleton_low]=optional_index(skin.skeleton);let [extension,extra]=write.extras(&skin.extensions,&skin.extras)?;let key=write.insert("gltf_skin",&[Cell::Integer(1),ordinal(position)?,inverse_high,inverse_low,skeleton_high,skeleton_low,text(&skin.name),extension,extra])?;write.check(skin.joints.len())?;for(position,joint)in skin.joints.iter().enumerate(){let [high,low]=index(*joint);write.insert("gltf_skin_joint",&[Cell::Integer(key),ordinal(position)?,high,low])?;}}Ok(())}
pub(super) fn reconstruct(read:&mut Read<'_,'_,'_>)->Result<Vec<GltfSkin>,String>{let rows=read.rows("gltf_skin",1,1,2)?;let mut skins=Vec::with_capacity(rows.len());for row in rows{let inverse_bind_matrices=read.optional_index(row,3)?;let skeleton=read.optional_index(row,5)?;let name=read.optional_text(row,7)?;let extensions=read.json(row,8)?;let extras=read.json(row,9)?;let rows=read.rows("gltf_skin_joint",1,row.rowid,2)?;let mut joints=Vec::with_capacity(rows.len());for row in rows{joints.push(read.index(row,3)?);}skins.push(GltfSkin{inverse_bind_matrices,skeleton,joints,name,extensions,extras});}Ok(skins)}
